import sys

def process_string(s):
    n = len(s)
    result = []
    for start in range(n):
        current = list(s[start:])
        i = 0
        while i < len(current) - 1:
            if current[i] == current[i + 1]:
                current.pop(i)
                current.pop(i)
            else:
                i += 1
        res = ''.join(current)
        result.append(res)

    for res in result:
        if len(res) > 10:
            print(f"{len(res)} {res[:5]}...{res[-2:]}")
        else:
            print(f"{len(res)} {res}")

if __name__ == "__main__":
    import sys
    s = sys.stdin.read().strip()
    process_string(s)
